ajustar_media <- function(y) { yh <- rep(NA_real_,length(y)); for(t in 2:length(y)) yh[t] <- mean(y[1:(t-1)]); list(yhat=yh, pronosticar=function(h) rep(mean(y),h), parametros=list()) }
ajustar_ingenuo <- function(y) { yh <- c(NA_real_,y[-length(y)]); list(yhat=yh,pronosticar=function(h) rep(tail(y,1),h),parametros=list()) }
ajustar_ingenuo_estacional <- function(y,s) { yh <- rep(NA_real_,length(y)); if(length(y)>s) yh[(s+1):length(y)] <- y[1:(length(y)-s)]; list(yhat=yh,pronosticar=function(h) sapply(seq_len(h),function(j)y[length(y)-s+(j-1)%%s+1]),parametros=list(s=s)) }
ajustar_mm <- function(y,k) { yh<-rep(NA_real_,length(y)); if(length(y)>k) for(t in (k+1):length(y)) yh[t]<-mean(y[(t-k):(t-1)]); list(yhat=yh,pronosticar=function(h) rep(mean(tail(y,k)),h),parametros=list(k=k)) }
ajustar_ses <- function(y,alpha) { yh<-rep(NA_real_,length(y)); yh[2]<-y[1]; for(t in 3:length(y)) yh[t]<-alpha*y[t-1]+(1-alpha)*yh[t-1]; list(yhat=yh,pronosticar=function(h) rep(tail(y,1)*alpha+(1-alpha)*tail(yh,1),h),parametros=list(alpha=alpha)) }
ajustar_dmm <- function(y,k) { fit<-ajustar_mm(y,k); list(yhat=fit$yhat,pronosticar=function(h) { n<-length(y); a<-mean(tail(y,k)); b<-mean(y[(n-2*k+1):(n-k)]); slope<-2*(a-b)/(k-1); a+(seq_len(h))*slope },parametros=list(k=k)) }
ajustar_tendencia <- function(y,tipo=c("lineal","cuadratica","exponencial")) { tipo<-match.arg(tipo); n<-length(y); x<-seq_len(n); z<-if(tipo=="exponencial") log(pmax(y,1e-8)) else y; grado<-if(tipo=="cuadratica") 2 else 1; X<-if(grado==1)cbind(1,x) else cbind(1,x,x^2); b<-solve(crossprod(X),crossprod(X,z)); yh<-rep(NA_real_,n); for(t in (grado+2):n) { xx<-seq_len(t-1); XX<-if(grado==1)cbind(1,xx) else cbind(1,xx,xx^2); bb<-solve(crossprod(XX),crossprod(XX,if(tipo=="exponencial")log(pmax(y[1:(t-1)],1e-8)) else y[1:(t-1)])); yh[t]<-if(tipo=="exponencial")exp(sum(bb*c(1,t))) else sum(bb*if(grado==1)c(1,t) else c(1,t,t^2)) }; list(yhat=yh,pronosticar=function(h)sapply(n+seq_len(h),function(tt)if(tipo=="exponencial")exp(sum(b*c(1,tt))) else sum(b*if(grado==1)c(1,tt) else c(1,tt,tt^2))),parametros=list(tipo=tipo,coef=b)) }
ajustar_tendencia_estacional <- function(y,s) { n<-length(y); tt<-seq_len(n); st<-factor((tt-1)%%s+1); X<-model.matrix(~tt+st); b<-solve(crossprod(X),crossprod(X,y)); yh<-rep(NA_real_,n); for(t in (s+3):n) { ii<-1:(t-1); xx<-model.matrix(~tt[ ii ] + factor((ii-1)%%s+1,levels=1:s)); yy<-y[ii]; bb<-solve(crossprod(xx),crossprod(xx,yy)); xt<-model.matrix(~tt[t] + factor((t-1)%%s+1,levels=1:s),xlev=list(`factor((ii - 1)%%s + 1, levels = 1:s)`=factor(1:s,levels=1:s))); yh[t]<-sum(xt*bb) }; list(yhat=yh,pronosticar=function(h) rep(mean(y),h),parametros=list(s=s,coef=b)) }
ajustar_holt <- function(y,alpha,beta) { n<-length(y); L<-y[1]; Tt<-y[2]-y[1]; yh<-rep(NA_real_,n); yh[2]<-L+Tt; for(t in 3:n) { oldL<-L; L<-alpha*y[t-1]+(1-alpha)*(L+Tt); Tt<-beta*(L-oldL)+(1-beta)*Tt; yh[t]<-L+Tt }; list(yhat=yh,pronosticar=function(h)L+Tt*seq_len(h),parametros=list(alpha=alpha,beta=beta)) }
ajustar_hw <- function(y,s,alpha,beta,gamma) { n<-length(y); if(n<2*s) stop("Se requieren dos ciclos") ; seas<-y[1:s]-mean(y[1:s]); L<-mean(y[1:s]); Tt<-(mean(y[(s+1):(2*s)])-L)/s; yh<-rep(NA_real_,n); for(t in (s+1):n) { j<-(t-1)%%s+1; yh[t]<-L+Tt+seas[j]; oldL<-L; L<-alpha*(y[t]-seas[j])+(1-alpha)*(L+Tt); Tt<-beta*(L-oldL)+(1-beta)*Tt; seas[j]<-gamma*(y[t]-L)+(1-gamma)*seas[j] }; list(yhat=yh,pronosticar=function(h)sapply(seq_len(h),function(j)L+j*Tt+seas[(n+j-1)%%s+1]),parametros=list(s=s,alpha=alpha,beta=beta,gamma=gamma)) }
ajustar_hw_mult <- function(y,s,alpha,beta,gamma) { z<-log(pmax(y,1e-8)); f<-ajustar_hw(z,s,alpha,beta,gamma); list(yhat=exp(f$yhat),pronosticar=function(h)exp(f$pronosticar(h)),parametros=c(f$parametros,list(escala="log"))) }
